function safeNode(name) {
  try {
    const item = $(name).first();
    if (!item) return { status: 'unavailable', reason: 'empty', data: null };
    const j = item.json ?? {};
    if (j.error || j.message === 'Error' || (typeof j.statusCode === 'number' && j.statusCode >= 400)) {
      return { status: 'unavailable', reason: j.error?.message || j.message || 'http_error', data: null };
    }
    const body = j.data && typeof j.data === 'object' && !Array.isArray(j.data) && (j.statusCode || j.headers)
      ? j.data
      : j;
    if (body && body.error && !body.hostname && !body.filesystems && !body.containers && !body.healthy && body.device_present === undefined) {
      return { status: 'unavailable', reason: String(body.error), data: null };
    }
    return { status: 'available', reason: null, data: body };
  } catch (e) {
    return { status: 'unavailable', reason: String(e.message || e), data: null };
  }
}

function round1(n) {
  const x = Number(n);
  return Number.isFinite(x) ? Math.round(x * 10) / 10 : null;
}

function parseDetails(d) {
  if (d == null) return {};
  if (typeof d === 'object') return d;
  try { return JSON.parse(d); } catch (e) { return {}; }
}

function readEvents(nodeName) {
  try {
    let rows = $(nodeName).all().map((i) => i.json).filter(Boolean);
    if (
      rows.length === 1 &&
      rows[0].event == null &&
      rows[0].severity == null &&
      rows[0].id == null &&
      rows[0].mount == null
    ) {
      rows = [];
    }
    return { available: true, rows };
  } catch (e) {
    return { available: false, rows: [], reason: String(e.message || e) };
  }
}

function isAttention(v) {
  return v === true || v === 't' || v === 'true';
}

function sevKey(s) {
  const k = String(s || 'info').toLowerCase();
  return ['info', 'warning', 'error', 'critical'].includes(k) ? k : 'info';
}

/**
 * Reconhece eventos de homologação/teste de forma estreita.
 * NÃO filtra monitores reais como "CRITICAL".
 */
function isTestEvent(e) {
  const source = String(e?.source || '').toLowerCase();
  const event = String(e?.event || '').toLowerCase();
  const message = String(e?.message || '');
  const details = parseDetails(e?.details);
  const monitor = String(details.monitor_name || details.monitorName || '').trim();
  const container = String(details.container_name || '').trim();

  if (source === 'manual_test' || source === 'production_test') return true;
  if (/_test$/.test(event)) return true;
  if (monitor.toUpperCase().startsWith('TESTE')) return true;
  if (/^teste(\b|\s|-)/i.test(monitor)) return true;
  if (/-test$/i.test(container)) return true;
  if (container.toLowerCase() === 'docker-guardian-test') return true;
  if (/^teste\s+controlado/i.test(message.trim())) return true;
  if (/^teste\s*-/i.test(message.trim())) return true;
  if (/nenhum(a)?\s+(falha|backup)\s+real/i.test(message)) return true;
  if (details.test === true || details.is_test === true || details.homologation === true) return true;

  // Recuperações explicitamente ligadas a incidente/evento de teste
  if (/_recovered$/.test(event) && /(_test\b|teste\s+controlado)/i.test(message)) return true;
  if (/(estado|incidente)\s+anterior\s+era:\s*\S*_test/i.test(message)) return true;

  return false;
}

function splitOperational(rows) {
  const operational = [];
  const ignored = [];
  for (const e of rows || []) {
    if (isTestEvent(e)) ignored.push(e);
    else operational.push(e);
  }
  return { operational, ignored };
}

function isRecoveryEvent(e) {
  const event = String(e?.event || '');
  const status = String(e?.status || '').toLowerCase();
  if (/_recovered$/.test(event)) return true;
  if (['storage_healthy', 'docker_healthy', 'backup_healthy', 'capacity_normal', 'disk_capacity_recovered'].includes(event)) {
    return true;
  }
  if (status === 'healthy' || status === 'resolved') return true;
  return false;
}

function isOpenIncidentEvent(e) {
  if (!e || isRecoveryEvent(e)) return false;
  const event = String(e.event || '');
  const sev = sevKey(e.severity);
  const status = String(e.status || '').toLowerCase();

  const incidentEvents = new Set([
    'service_down',
    'container_stopped',
    'container_unhealthy',
    'container_restarting',
    'container_dead',
    'restart_count_increased',
    'filesystem_read_only',
    'storage_device_missing',
    'storage_unmounted',
    'disk_space_warning',
    'disk_space_error',
    'disk_space_critical',
    'disk_capacity_warning',
    'disk_capacity_error',
    'disk_capacity_critical',
    'backup_failed',
    'backup_overdue',
    'database_dump_failed',
    'backup_storage_low',
  ]);

  if (incidentEvents.has(event)) return true;
  if ((sev === 'critical' || sev === 'error') && status === 'active') return true;
  if (sev === 'warning' && status === 'active' && (event.startsWith('service_') || event.startsWith('storage_') || event.startsWith('disk_') || event.startsWith('backup_') || event.startsWith('container_'))) {
    return true;
  }
  return false;
}

function entityKey(e) {
  const details = parseDetails(e?.details);
  const source = String(e?.source || '');
  const event = String(e?.event || '');
  const component = String(e?.component || '');

  if (source === 'uptime_kuma' || component === 'service_monitoring' || event.startsWith('service_')) {
    const id = details.monitor_id != null && String(details.monitor_id) !== ''
      ? String(details.monitor_id)
      : String(details.monitor_name || details.monitorName || 'unknown');
    return `service:${id}`;
  }
  if (source === 'docker_guardian' || component === 'docker' || event.startsWith('container_') || event === 'restart_count_increased') {
    return `docker:${details.container_name || 'unknown'}`;
  }
  if (source === 'storage_guardian' || component === 'storage' || event.startsWith('storage_') || event.startsWith('filesystem_')) {
    return 'storage:primary';
  }
  if (source === 'backup_verification' || component === 'backup' || event.startsWith('backup_') || event.includes('database_dump')) {
    return 'backup:primary';
  }
  if (source === 'disk_capacity' || event.startsWith('disk_') || event.startsWith('capacity_')) {
    return `disk:${details.mount || 'unknown'}`;
  }
  return `${source || 'unknown'}:${component || 'unknown'}`;
}

function eventTime(e) {
  const t = new Date(e.timestamp || e.created_at).getTime();
  return Number.isFinite(t) ? t : 0;
}

/** Estado mais recente por entidade → só conta como unresolved se o último evento ainda for incidente. */
function findUnresolvedIncidents(rows) {
  const latest = {};
  for (const e of rows || []) {
    const key = entityKey(e);
    const ts = eventTime(e);
    if (!latest[key] || ts >= latest[key].ts) {
      latest[key] = { ts, event: e };
    }
  }

  const unresolved = [];
  for (const [key, item] of Object.entries(latest)) {
    const e = item.event;
    if (isRecoveryEvent(e)) continue;
    if (!isOpenIncidentEvent(e)) continue;
    const details = parseDetails(e.details);
    unresolved.push({
      entity: key,
      source: e.source ?? null,
      component: e.component ?? null,
      event: e.event ?? null,
      severity: e.severity ?? null,
      status: e.status ?? null,
      message: e.message ?? null,
      monitor_name: details.monitor_name || details.monitorName || null,
      container_name: details.container_name || null,
      mount: details.mount || null,
      created_at: e.created_at ?? e.timestamp ?? null,
    });
  }

  const rank = { critical: 1, error: 2, warning: 3, info: 4 };
  unresolved.sort((a, b) => {
    const ra = rank[sevKey(a.severity)] ?? 9;
    const rb = rank[sevKey(b.severity)] ?? 9;
    if (ra !== rb) return ra - rb;
    return String(b.created_at || '').localeCompare(String(a.created_at || ''));
  });
  return unresolved;
}

function aggregateEvents(rows) {
  const sev = { info: 0, warning: 0, error: 0, critical: 0 };
  let requires_attention = 0;
  let recoveries = 0;
  const by_source = {};
  const by_component = {};
  const by_event = {};

  for (const e of rows) {
    const s = sevKey(e.severity);
    sev[s] += 1;
    if (isAttention(e.requires_attention)) requires_attention += 1;
    const ev = String(e.event || 'unknown');
    if (/_recovered$/.test(ev)) recoveries += 1;
    const src = String(e.source || 'unknown');
    const comp = String(e.component || 'unknown');
    by_source[src] = (by_source[src] || 0) + 1;
    by_component[comp] = (by_component[comp] || 0) + 1;
    by_event[ev] = (by_event[ev] || 0) + 1;
  }

  const rank = { critical: 1, error: 2, warning: 3, info: 4 };
  const incidentRows = rows.filter((e) => ['critical', 'error', 'warning'].includes(sevKey(e.severity)));
  const top_incidents = [...incidentRows]
    .sort((a, b) => {
      const ra = rank[sevKey(a.severity)] ?? 9;
      const rb = rank[sevKey(b.severity)] ?? 9;
      if (ra !== rb) return ra - rb;
      return String(b.created_at || b.timestamp || '').localeCompare(String(a.created_at || a.timestamp || ''));
    })
    .slice(0, 10)
    .map((e) => ({
      source: e.source ?? null,
      component: e.component ?? null,
      event: e.event ?? null,
      severity: e.severity ?? null,
      status: e.status ?? null,
      message: e.message ?? null,
      requires_attention: isAttention(e.requires_attention),
      created_at: e.created_at ?? e.timestamp ?? null,
    }));

  const top_recoveries = rows
    .filter((e) => /_recovered$/.test(String(e.event || '')))
    .sort((a, b) => String(b.created_at || '').localeCompare(String(a.created_at || '')))
    .slice(0, 10)
    .map((e) => ({
      source: e.source ?? null,
      event: e.event ?? null,
      message: e.message ?? null,
      created_at: e.created_at ?? e.timestamp ?? null,
    }));

  return {
    status: 'available',
    total: rows.length,
    info: sev.info,
    warning: sev.warning,
    error: sev.error,
    critical: sev.critical,
    requires_attention,
    recoveries,
    by_source,
    by_component,
    by_event,
    top_incidents,
    top_recoveries,
  };
}

function classifyDelta(current, previous) {
  if (previous === null || previous === undefined) {
    return { current_week: current, previous_week: null, classification: 'insufficient_data' };
  }
  let classification = 'stable';
  if (current < previous) classification = 'improving';
  else if (current > previous) classification = 'worsening';
  return { current_week: current, previous_week: previous, classification };
}

function serviceAnalysis(rows) {
  const serviceEvents = rows.filter((e) => e.source === 'uptime_kuma' || e.component === 'service_monitoring');
  const downs = serviceEvents.filter((e) => e.event === 'service_down');
  const recovered = serviceEvents.filter((e) => e.event === 'service_recovered');

  const byService = {};
  for (const e of downs) {
    const d = parseDetails(e.details);
    const key = d.monitor_name || d.monitorName || d.name || d.monitor_id || 'unknown';
    if (!byService[key]) byService[key] = { service: key, service_down: 0, service_recovered: 0, known_downtime_seconds: null };
    byService[key].service_down += 1;
  }
  for (const e of recovered) {
    const d = parseDetails(e.details);
    const key = d.monitor_name || d.monitorName || d.name || d.monitor_id || 'unknown';
    if (!byService[key]) byService[key] = { service: key, service_down: 0, service_recovered: 0, known_downtime_seconds: null };
    byService[key].service_recovered += 1;
  }

  const byMonitor = {};
  for (const e of serviceEvents) {
    const d = parseDetails(e.details);
    const mid = String(d.monitor_id ?? d.monitor_name ?? d.name ?? 'unknown');
    if (!byMonitor[mid]) byMonitor[mid] = [];
    byMonitor[mid].push({
      event: e.event,
      ts: eventTime(e),
      name: d.monitor_name || d.monitorName || d.name || mid,
    });
  }
  let knownDowntimeTotal = 0;
  let pairs = 0;
  for (const mid of Object.keys(byMonitor)) {
    const seq = byMonitor[mid].filter((x) => Number.isFinite(x.ts)).sort((a, b) => a.ts - b.ts);
    let openDown = null;
    let serviceDowntime = 0;
    for (const item of seq) {
      if (item.event === 'service_down') {
        if (openDown == null) openDown = item.ts;
      } else if (item.event === 'service_recovered' && openDown != null) {
        const dur = Math.max(0, Math.floor((item.ts - openDown) / 1000));
        serviceDowntime += dur;
        knownDowntimeTotal += dur;
        pairs += 1;
        openDown = null;
      }
    }
    const name = seq[0]?.name || mid;
    if (byService[name]) byService[name].known_downtime_seconds = serviceDowntime || null;
  }

  const most_unstable = Object.values(byService)
    .sort((a, b) => b.service_down - a.service_down || b.service_recovered - a.service_recovered)
    .slice(0, 5);

  return {
    status: 'available',
    source: 'hestia_events',
    service_down: downs.length,
    service_recovered: recovered.length,
    most_unstable,
    most_affected_service: most_unstable[0]?.service || null,
    known_downtime_seconds_total: pairs > 0 ? knownDowntimeTotal : null,
    known_downtime_pairs: pairs,
    uptime_percent: null,
    note: pairs > 0
      ? 'Duração estimada apenas entre pares DOWN→RECOVERED observados; uptime percentual não calculado.'
      : 'Sem pares DOWN→RECOVERED suficientes para estimar duração; uptime percentual não inventado.',
  };
}

function dockerEventsAnalysis(rows) {
  const dockerRows = rows.filter((e) => e.source === 'docker_guardian' || e.component === 'docker');
  const types = [
    'container_stopped',
    'container_unhealthy',
    'container_restarting',
    'container_dead',
    'container_recovered',
    'restart_count_increased',
  ];
  const counts = {};
  for (const t of types) counts[t] = dockerRows.filter((e) => e.event === t).length;

  const byContainer = {};
  for (const e of dockerRows) {
    const d = parseDetails(e.details);
    const name = d.container_name || d.name || 'unknown';
    if (!byContainer[name]) byContainer[name] = { container: name, incidents: 0, recoveries: 0, events: {} };
    byContainer[name].events[e.event] = (byContainer[name].events[e.event] || 0) + 1;
    if (e.event === 'container_recovered') byContainer[name].recoveries += 1;
    else if (types.includes(e.event) && e.event !== 'container_recovered') byContainer[name].incidents += 1;
  }

  const most_problematic = Object.values(byContainer)
    .sort((a, b) => b.incidents - a.incidents || b.recoveries - a.recoveries)
    .slice(0, 5);

  return {
    week: {
      ...counts,
      total_incidents: types.filter((t) => t !== 'container_recovered').reduce((a, t) => a + counts[t], 0),
      recoveries: counts.container_recovered,
      most_problematic,
    },
  };
}

function storageEventsAnalysis(rows) {
  const storageRows = rows.filter((e) =>
    e.source === 'storage_guardian' ||
    e.component === 'storage' ||
    String(e.event || '').startsWith('storage_') ||
    String(e.event || '').startsWith('filesystem_') ||
    String(e.event || '').includes('disk_space')
  );
  const keys = {
    mount_issues: storageRows.filter((e) => /mount|device_missing|storage_device/i.test(String(e.event))).length,
    readonly: storageRows.filter((e) => /read_only|readonly|filesystem_read_only/i.test(String(e.event))).length,
    io_or_kernel: storageRows.filter((e) => /io_error|kernel|buffer|usb/i.test(String(e.event) + ' ' + String(e.message || ''))).length,
    disappear: storageRows.filter((e) => /missing|disappear|not_found|unmounted/i.test(String(e.event))).length,
    recovery: storageRows.filter((e) => e.event === 'storage_recovered').length,
    total: storageRows.length,
  };
  return { week: keys, events_sample: storageRows.slice(0, 5).map((e) => ({ event: e.event, severity: e.severity, created_at: e.created_at })) };
}

function backupEventsAnalysis(rows) {
  const backupRows = rows.filter((e) => e.source === 'backup_verification' || e.component === 'backup' || String(e.event || '').startsWith('backup_') || String(e.event || '').includes('database_dump'));
  const success = backupRows.filter((e) => /success|healthy|recovered/i.test(String(e.event))).length;
  const failed = backupRows.filter((e) => /fail/i.test(String(e.event))).length;
  const overdue = backupRows.filter((e) => /overdue/i.test(String(e.event))).length;
  const dump_failed = backupRows.filter((e) => /database_dump_failed/i.test(String(e.event))).length;
  const storage_low = backupRows.filter((e) => /backup_storage_low/i.test(String(e.event))).length;
  return {
    week: {
      backup_success_or_recovered: success,
      backup_failed: failed,
      backup_overdue: overdue,
      database_dump_failed: dump_failed,
      backup_storage_low: storage_low,
      total_events: backupRows.length,
    },
  };
}

function capacityGrowth(historyRows, currentFilesystems) {
  const byMount = {};
  for (const r of historyRows) {
    const m = r.mount;
    if (!m) continue;
    if (!byMount[m]) byMount[m] = [];
    byMount[m].push({
      timestamp: r.timestamp || r.created_at,
      used_bytes: r.used_bytes != null ? Number(r.used_bytes) : null,
      used_percent: r.used_percent != null ? Number(r.used_percent) : null,
      total_bytes: r.total_bytes != null ? Number(r.total_bytes) : null,
      free_bytes: r.free_bytes != null ? Number(r.free_bytes) : null,
    });
  }

  const mounts = {};
  const mountList = (currentFilesystems || []).map((f) => f.mount).concat(Object.keys(byMount));
  const uniqueMounts = [...new Set(mountList.filter(Boolean))];

  for (const mount of uniqueMounts) {
    const series = (byMount[mount] || []).filter((p) => p.used_bytes != null && p.timestamp)
      .sort((a, b) => new Date(a.timestamp) - new Date(b.timestamp));
    if (series.length < 2) {
      mounts[mount] = {
        available: false,
        reason: 'history_building',
        samples: series.length,
        message: 'Histórico de crescimento ainda em construção.',
      };
      continue;
    }
    const first = series[0];
    const last = series[series.length - 1];
    const ms = new Date(last.timestamp) - new Date(first.timestamp);
    const days = ms / (1000 * 60 * 60 * 24);
    if (!(days >= 1)) {
      mounts[mount] = {
        available: false,
        reason: 'insufficient_span',
        samples: series.length,
        message: 'Histórico insuficiente (intervalo < 1 dia).',
      };
      continue;
    }
    const delta = last.used_bytes - first.used_bytes;
    mounts[mount] = {
      available: true,
      samples: series.length,
      from: first.timestamp,
      to: last.timestamp,
      days: Math.round(days * 10) / 10,
      delta_used_bytes: delta,
      bytes_per_day: Math.round(delta / days),
      used_percent_from: first.used_percent,
      used_percent_to: last.used_percent,
    };
  }

  return {
    status: 'available',
    available: Object.values(mounts).some((m) => m.available === true),
    mounts,
    note: Object.values(mounts).some((m) => m.available === true)
      ? null
      : 'Histórico de crescimento ainda em construção. Backlog: integrar 05 Disk Capacity para snapshot periódico (ex.: 1x/dia).',
  };
}

const now = new Date();
const toIso = now.toISOString();
const fromCurrent = new Date(now.getTime() - 7 * 24 * 60 * 60 * 1000).toISOString();
const fromPrevious = new Date(now.getTime() - 14 * 24 * 60 * 60 * 1000).toISOString();
const toPrevious = fromCurrent;

const systemSrc = safeNode('Get System');
const storageSrc = safeNode('Get Storage');
const diskSrc = safeNode('Get Disk Capacity');
const dockerSrc = safeNode('Get Docker');
const backupSrc = safeNode('Get Backups');

const currentEv = readEvents('Get Current Week Events');
const previousEv = readEvents('Get Previous Week Events');
const histEv = readEvents('Get Capacity History');

const currentRaw = currentEv.available ? currentEv.rows : [];
const previousRaw = previousEv.available ? previousEv.rows : [];
const currentSplit = splitOperational(currentRaw);
const previousSplit = splitOperational(previousRaw);
const currentOps = currentSplit.operational;
const previousOps = previousSplit.operational;

const currentAgg = currentEv.available
  ? aggregateEvents(currentOps)
  : { status: 'unavailable', reason: currentEv.reason || 'query_failed', total: 0, info: 0, warning: 0, error: 0, critical: 0, requires_attention: 0, recoveries: 0, by_source: {}, by_component: {}, by_event: {}, top_incidents: [], top_recoveries: [] };
const previousAgg = previousEv.available
  ? aggregateEvents(previousOps)
  : { status: 'unavailable', reason: previousEv.reason || 'query_failed', total: 0, info: 0, warning: 0, error: 0, critical: 0, requires_attention: 0, recoveries: 0, by_source: {}, by_component: {}, by_event: {}, top_incidents: [], top_recoveries: [] };

const unresolved = currentEv.available ? findUnresolvedIncidents(currentOps) : [];
const unresolvedCritical = unresolved.filter((u) => sevKey(u.severity) === 'critical');
const unresolvedError = unresolved.filter((u) => sevKey(u.severity) === 'error');
const unresolvedWarning = unresolved.filter((u) => sevKey(u.severity) === 'warning');

const test_events_ignored = {
  current_week: currentSplit.ignored.length,
  previous_week: previousSplit.ignored.length,
  total: currentSplit.ignored.length + previousSplit.ignored.length,
  samples: currentSplit.ignored.slice(0, 8).map((e) => ({
    source: e.source ?? null,
    event: e.event ?? null,
    monitor_name: parseDetails(e.details).monitor_name || null,
    container_name: parseDetails(e.details).container_name || null,
    message: e.message ?? null,
  })),
};

const system = systemSrc.status === 'available'
  ? {
      status: 'available',
      hostname: systemSrc.data.hostname ?? null,
      uptime_seconds: systemSrc.data.uptime_seconds ?? null,
      uptime_human: systemSrc.data.uptime_human ?? null,
      cpu_percent_current: systemSrc.data.cpu?.usage_percent ?? null,
      load_1m: round1(systemSrc.data.cpu?.load_1m),
      load_5m: round1(systemSrc.data.cpu?.load_5m),
      load_15m: round1(systemSrc.data.cpu?.load_15m),
      ram_percent_current: systemSrc.data.memory?.used_percent ?? null,
      ram_used_bytes: systemSrc.data.memory?.used_bytes ?? null,
      ram_total_bytes: systemSrc.data.memory?.total_bytes ?? null,
      note: 'Valores pontuais atuais — não são médias semanais.',
    }
  : { status: 'unavailable', reason: systemSrc.reason };

const storageWeek = storageEventsAnalysis(currentOps);
const storage = storageSrc.status === 'available'
  ? {
      status: 'available',
      healthy: storageSrc.data.healthy === true,
      device_present: storageSrc.data.device_present === true,
      mounted: storageSrc.data.mounted === true,
      mode: storageSrc.data.mode ?? null,
      filesystem: storageSrc.data.filesystem ?? null,
      device: storageSrc.data.device ?? null,
      mountpoint: storageSrc.data.mountpoint ?? null,
      identity_match: storageSrc.data.identity_match === true,
      used_percent: storageSrc.data.used_percent ?? null,
      kernel_errors: storageSrc.data.kernel_errors ?? null,
      emergency_ro: storageSrc.data.emergency_ro === true,
      week: storageWeek.week,
    }
  : { status: 'unavailable', reason: storageSrc.reason, week: storageWeek.week };

const disk_capacity = diskSrc.status === 'available'
  ? {
      status: 'available',
      thresholds: diskSrc.data.thresholds ?? null,
      worst_capacity_state: diskSrc.data.summary?.worst_capacity_state ?? null,
      filesystems: (diskSrc.data.filesystems || []).map((fs) => ({
        mount: fs.mount,
        device: fs.device ?? null,
        used_percent: fs.used_percent,
        free_gb: fs.free_gb,
        total_gb: fs.total_gb,
