// Trends: apenas eventos operacionais; semana anterior vazia => insufficient_data
const prevOk = previousEv.available && previousAgg.status === 'available' && previousAgg.total > 0;
const prevTotalIncidents = prevOk ? (previousAgg.warning + previousAgg.error + previousAgg.critical) : null;
