const prevDockerInc = prevOk
  ? (previousAgg.by_event.container_stopped || 0) + (previousAgg.by_event.container_unhealthy || 0) + (previousAgg.by_event.container_restarting || 0) + (previousAgg.by_event.container_dead || 0) + (previousAgg.by_event.restart_count_increased || 0)
