    (docker.status === 'available' && ((docker.summary?.unhealthy || 0) > 0 || (docker.summary?.restarting || 0) > 0 || (docker.summary?.stopped || 0) > 0 || (docker.problem_containers || []).length > 0)) ||
    (backups.status === 'available' && backups.healthy !== true);

  if (repetitiveErrors) {
    overall = 'degraded';
    reasons.push('repetitive_operational_incidents');
  }
  if (liveDegraded) {
    overall = 'degraded';
    reasons.push('live_degraded');
  }

  const unavailableLive = [system, storage, disk_capacity, docker, backups].filter((s) => s.status === 'unavailable').length;
  if (unavailableLive > 0) {
    overall = overall === 'healthy' ? 'degraded' : overall;
    reasons.push('partial_source_unavailable');
  }
}

if (overall === 'healthy') {
  if (unresolvedWarning.length > 0 || currentAgg.warning > 0) {
    overall = 'attention';
    reasons.push(unresolvedWarning.length > 0 ? 'unresolved_warning_open' : 'weekly_warnings');
  } else if (overall_trend === 'worsening') {
    overall = 'attention';
    reasons.push('trend_worsening');
  } else if ((currentAgg.error + currentAgg.critical) > 0 && unresolved.length === 0) {
    overall = 'attention';
    reasons.push('resolved_incidents_in_week');
  }
} else if (overall === 'degraded' && overall_trend === 'worsening') {
  reasons.push('trend_worsening');
}

const summaryText =
  overall === 'healthy'
    ? 'Sistema estável durante a semana.'
    : overall === 'attention'
      ? 'Semana operacional com pontos de atenção.'
      : overall === 'degraded'
        ? 'Degradação ou erros relevantes observados na semana.'
        : 'Condição crítica — atenção imediata recomendada.';

const hestiaInsight =
  overall === 'healthy' && overall_trend !== 'worsening'
    ? 'Não identifiquei degradação progressiva esta semana.'
    : overall_trend === 'worsening'
      ? 'Há sinais de piora em relação à semana anterior — vale acompanhar de perto.'
      : overall_trend === 'improving'
        ? 'Os indicadores da semana melhoraram em relação ao período anterior.'
        : overall_trend === 'insufficient_data'
