            : 'Há pontos que merecem acompanhamento nesta semana.';

const sources = { available: [], unavailable: [], not_monitored: [] };
for (const [k, v] of Object.entries({ system, storage, disk_capacity, docker, backups, services, events_current: currentAgg, events_previous: previousAgg, capacity_history })) {
