function fmtDateSP(iso) {
  try {
    return new Intl.DateTimeFormat('pt-BR', {
      timeZone: 'America/Sao_Paulo',
      day: '2-digit',
      month: '2-digit',
    }).format(new Date(iso));
  } catch (e) {
    return String(iso || '').slice(0, 10);
  }
}

function mountLabel(m) {
  if (m === '/') return 'NVMe /';
  if (m === '/srv/storage') return 'RAID /srv/storage';
  return m;
}

const sys = snap.system;
const storage = snap.storage;
