function sqlLit(v) {
  if (v === null || v === undefined) return 'NULL';
  if (typeof v === 'number' && Number.isFinite(v)) return String(v);
  return "'" + String(v).replace(/'/g, "''") + "'";
}

const values = rows.map((r) => {
  const mount = String(r.mount || '');
  if (!/^[\w./-]+$/.test(mount)) return null;
  return `(${sqlLit(r.timestamp)}::timestamptz, ${sqlLit(mount)}, ${sqlLit(r.total_bytes)}, ${sqlLit(r.used_bytes)}, ${sqlLit(r.free_bytes)}, ${sqlLit(r.used_percent)})`;
}).filter(Boolean);

if (!values.length) {
  return [{
    json: {
      snapshot: snap,
      alert,
      capacity_persist: { attempted: false, reason: 'no_valid_rows' },
    },
  }];
}

const query = `INSERT INTO omeab_capacity_history (timestamp, mount, total_bytes, used_bytes, free_bytes, used_percent) VALUES ${values.join(', ')};`;

return [{
  json: {
    snapshot: snap,
    alert,
    capacity_persist: { attempted: true, rows: values.length },
    capacity_insert_sql: query,
  },
}];

